(7524534, 1202617, 191043, '<td valign="top">//www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1202617#</td>', '//www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1202617#', '2017-07-20 21:35:26.000000', NULL, 1),
(7524560, 1202509, 182284, '<td valign="top">I have to say you went all out for this challenge. I hope you had help making the paper boats. I like what you''ve done with the toned B&amp;W. 7</td>', 'I have to say you went all out for this challenge. I hope you had help making the paper boats. I like what you''ve done with the toned B&W. 7', '2017-07-21 00:31:50.000000', NULL, 1),
(7524561, 1202805, 182284, '<td valign="top">You may do quite well with this.</td>', 'You may do quite well with this.', '2017-07-21 00:33:10.000000', NULL, 1),
(7524562, 1202533, 182284, '<td valign="top">Love your title! I think I would have tried a different composition. 5</td>', 'Love your title! I think I would have tried a different composition. 5', '2017-07-21 00:34:32.000000', NULL, 1),
(7524563, 1202462, 182284, '<td valign="top">My brother used to fly a seaplane. Nice and colorful.5</td>', 'My brother used to fly a seaplane. Nice and colorful.5', '2017-07-21 00:36:59.000000', NULL, 1),
(7524591, 1202512, 30982, '<td valign="top">Wow.  Best in show.  Amazing contrast, light, everything.</td>', 'Wow.  Best in show.  Amazing contrast, light, everything.', '2017-07-21 02:16:01.000000', NULL, 1),
(7524643, 1202757, 113156, '<td valign="top">Must have been nice, great tones.</td>', 'Must have been nice, great tones.', '2017-07-21 03:11:33.000000', NULL, 1),
(7524648, 1202804, 113156, '<td valign="top">I like the angle you took this from.</td>', 'I like the angle you took this from.', '2017-07-21 03:14:42.000000', NULL, 1),
(7524653, 1202397, 113156, '<td valign="top">I would have cropped a bit of the bottom or top to make the composition better, as it is it''s to cental. Nice image though.</td>', 'I would have cropped a bit of the bottom or top to make the composition better, as it is it''s to cental. Nice image though.', '2017-07-21 03:18:23.000000', NULL, 1),
(7524688, 1202493, 39880, '<td valign="top">I like this view.  Processing made it interesting.</td>', 'I like this view.  Processing made it interesting.', '2017-07-21 10:54:41.000000', NULL, 1),
(7524689, 1202793, 39880, '<td valign="top">Is this the headless boat-person?  Interesting take.</td>', 'Is this the headless boat-person?  Interesting take.', '2017-07-21 10:55:28.000000', NULL, 1),
(7524690, 1202803, 39880, '<td valign="top">Great angle.  I like this one.</td>', 'Great angle.  I like this one.', '2017-07-21 10:56:10.000000', NULL, 1),
(7524698, 1202783, 173844, '<td valign="top">Clear favorite for the action alone.  The scenery, too, is exciting --   wonderful columned cliffs, the leading flow of the river and the lowering sky.  Gets the heart racing.</td>', 'Clear favorite for the action alone.  The scenery, too, is exciting --   wonderful columned cliffs, the leading flow of the river and the lowering sky.  Gets the heart racing.', '2017-07-21 12:38:33.000000', NULL, 1),
(7524702, 1202333, 61552, '<td valign="top">Very nice.  Looks like a place out of a Grimm''s Fairy Tale.  I wouldn''t have cut the building on the right in half, myself, but I still give you a 10.</td>', 'Very nice.  Looks like a place out of a Grimm''s Fairy Tale.  I wouldn''t have cut the building on the right in half, myself, but I still give you a 10.', '2017-07-21 13:09:42.000000', NULL, 1),
(7524708, 1202745, 173844, '<td valign="top">Fine portrait of a dignified old ship, rusting yet still afloat.  The line of the rope is in a strong perspective, tethering the ship to the shore, its reflection finally a wisp among small stones.  Aft, the ship seems to melt into the sunrise or sunset.  The placid mood is ennobling.  My second favorite.</td>', 'Fine portrait of a dignified old ship, rusting yet still afloat.  The line of the rope is in a strong perspective, tethering the ship to the shore, its reflection finally a wisp among small stones.  Aft, the ship seems to melt into the sunrise or sunset.  The placid mood is ennobling.  My second favorite.', '2017-07-21 14:06:14.000000', NULL, 1),
(7524710, 1202397, 173844, '<td valign="top">The French bulldog brings a cheerful note to what is already a fine, confidant image.  Both intimate and expansive, the interplay of tones and textures is a joy to behold.</td>', 'The French bulldog brings a cheerful note to what is already a fine, confidant image.  Both intimate and expansive, the interplay of tones and textures is a joy to behold.', '2017-07-21 14:13:05.000000', NULL, 1),
(7524713, 1202793, 56452, '<td valign="top">Excellent! Love the detail of water droplets off the oar.</td>', 'Excellent! Love the detail of water droplets off the oar.', '2017-07-21 14:19:48.000000', NULL, 1),
(7524730, 1202757, 173844, '<td valign="top">An often-visited viewpoint, but this is done so well, with such an appealing interplay of light and dark, that we simply relax into an enchanting morning and the promise of a happy day.  A virtue of this viewpoint is being right down on the water with the paddler, deeply involved in the adventure.  Very enjoyable.</td>', 'An often-visited viewpoint, but this is done so well, with such an appealing interplay of light and dark, that we simply relax into an enchanting morning and the promise of a happy day.  A virtue of this viewpoint is being right down on the water with the paddler, deeply involved in the adventure.  Very enjoyable.', '2017-07-21 16:40:13.000000', NULL, 1),
(7524732, 1202804, 173844, '<td valign="top">I especially like the straightforwardness of this image, and the bold balance of the blocky ferry on the right and the generous expanse of water on the left, linked by the sky.</td>', 'I especially like the straightforwardness of this image, and the bold balance of the blocky ferry on the right and the generous expanse of water on the left, linked by the sky.', '2017-07-21 16:47:22.000000', NULL, 1),
(7524733, 1202803, 173844, '<td valign="top">A wonderful immediacy with terrific depth.  You can almost hear the shrieking of the gulls and the muttering of the motorboat.</td>', 'A wonderful immediacy with terrific depth.  You can almost hear the shrieking of the gulls and the muttering of the motorboat.', '2017-07-21 16:50:20.000000', NULL, 1),
(7524734, 1202792, 173844, '<td valign="top">A fine delicacy of kayaks and paddlers on a muscular expanse of water, below an expressive band of clouds.  The sepia tint yanks the image back centuries, off the Pacific Northwest coast, perhaps.  Excellent.</td>', 'A fine delicacy of kayaks and paddlers on a muscular expanse of water, below an expressive band of clouds.  The sepia tint yanks the image back centuries, off the Pacific Northwest coast, perhaps.  Excellent.', '2017-07-21 17:01:46.000000', NULL, 1),
(7524735, 1202759, 173844, '<td valign="top">Fine feeling of the quiet depth of night.  My personal desire is for the boat to be less brightly lit.  Still, I''m liking this.</td>', 'Fine feeling of the quiet depth of night.  My personal desire is for the boat to be less brightly lit.  Still, I''m liking this.', '2017-07-21 17:07:08.000000', NULL, 1),
(7524737, 1202789, 173844, '<td valign="top">Lovely pastel colors.  I like the out of focus foreground.</td>', 'Lovely pastel colors.  I like the out of focus foreground.', '2017-07-21 17:09:36.000000', NULL, 1),
(7524738, 1202333, 173844, '<td valign="top">Great realism and immediacy.  Feels like we''re getting a peek of a hidden cove.  What most struck me, though, is how the sky looks like ocean surf at 90 degrees  to the scene.  Pleasantly disconcerting.</td>', 'Great realism and immediacy.  Feels like we''re getting a peek of a hidden cove.  What most struck me, though, is how the sky looks like ocean surf at 90 degrees  to the scene.  Pleasantly disconcerting.', '2017-07-21 17:16:08.000000', NULL, 1),
(7524739, 1202796, 173844, '<td valign="top">Has the nostalgic look and feel of an old post card.  The murky framing effectively concentrates focus on the boat and its passengers.  Exemplifies simple pleasures.</td>', 'Has the nostalgic look and feel of an old post card.  The murky framing effectively concentrates focus on the boat and its passengers.  Exemplifies simple pleasures.', '2017-07-21 17:22:49.000000', NULL, 1),
(7524742, 1202512, 173844, '<td valign="top">Quirky.  Tough to get a handle on the scale.  Though I think I know what''s going on here, it''s pleasant to believe a child is going to reach down and play with these six inch toys.  Strong image.</td>', 'Quirky.  Tough to get a handle on the scale.  Though I think I know what''s going on here, it''s pleasant to believe a child is going to reach down and play with these six inch toys.  Strong image.', '2017-07-21 17:29:57.000000', NULL, 1),
(7524743, 1202801, 173844, '<td valign="top">Great perspective.</td>', 'Great perspective.', '2017-07-21 17:30:42.000000', NULL, 1),
(7524744, 1202547, 173844, '<td valign="top">Solid, well-balanced image.  Nice feeling of anticipation.</td>', 'Solid, well-balanced image.  Nice feeling of anticipation.', '2017-07-21 17:33:37.000000', NULL, 1),
(7524745, 1202733, 173844, '<td valign="top">Fine action shot.</td>', 'Fine action shot.', '2017-07-21 17:34:23.000000', NULL, 1),
(7524746, 1202810, 173844, '<td valign="top">Beautiful sunrise.  If the horizon weren''t centered I think the inherent serenity of the scene would be enhanced.</td>', 'Beautiful sunrise.  If the horizon weren''t centered I think the inherent serenity of the scene would be enhanced.', '2017-07-21 17:37:53.000000', NULL, 1),
(7524747, 1202487, 173844, '<td valign="top">Fine perspective, putting the viewer right on the boat.</td>', 'Fine perspective, putting the viewer right on the boat.', '2017-07-21 17:39:46.000000', NULL, 1),
(7524748, 1202626, 173844, '<td valign="top">I kind of like this, but just can''t fully buy into it.</td>', 'I kind of like this, but just can''t fully buy into it.', '2017-07-21 17:42:02.000000', NULL, 1),
(7524749, 1202533, 173844, '<td valign="top">Lot of oomph here, and room for commentary --   by someone else.  A brief moment, stark and wistful, caught with great discernment.</td>', 'Lot of oomph here, and room for commentary --   by someone else.  A brief moment, stark and wistful, caught with great discernment.', '2017-07-21 17:48:41.000000', NULL, 1),
(7524750, 1202499, 173844, '<td valign="top">Fine black and white.  Those signalling bumps on the yardarms kind of clunk up the profile, but that''s the way it goes.  Regardless, a finely textured image.</td>', 'Fine black and white.  Those signalling bumps on the yardarms kind of clunk up the profile, but that''s the way it goes.  Regardless, a finely textured image.', '2017-07-21 18:03:07.000000', NULL, 1),
(7524751, 1202517, 173844, '<td valign="top">Well-presented candid moment, enhanced by the sepia toning.  Is this what''s meant by "mucking about"?</td>', 'Well-presented candid moment, enhanced by the sepia toning.  Is this what''s meant by "mucking about"?', '2017-07-21 18:06:31.000000', NULL, 1),
(7524752, 1202775, 173844, '<td valign="top">I like this picture for its quirky balance.</td>', 'I like this picture for its quirky balance.', '2017-07-21 18:09:17.000000', NULL, 1),
(7524753, 1202331, 173844, '<td valign="top">Yes, and lovely colors, that transition from blue to pink.</td>', 'Yes, and lovely colors, that transition from blue to pink.', '2017-07-21 18:14:52.000000', NULL, 1),
(7524754, 1202771, 173844, '<td valign="top">Having fun.  Well-balanced, makes me smile.</td>', 'Having fun.  Well-balanced, makes me smile.', '2017-07-21 18:25:01.000000', NULL, 1),
(7524755, 1202639, 173844, '<td valign="top">A pretty day.</td>', 'A pretty day.', '2017-07-21 18:26:13.000000', NULL, 1),
(7524756, 1202270, 173844, '<td valign="top">The contrast of these funny-looking (to me, at least) crafts with a gorgeous sunrise brings on a smile.  It''s an affirmation of the world in all its variety.  Quite sumptuous, in its own way. The pier frames the photo nicely on the right.</td>', 'The contrast of these funny-looking (to me, at least) crafts with a gorgeous sunrise brings on a smile.  It''s an affirmation of the world in all its variety.  Quite sumptuous, in its own way. The pier frames the photo nicely on the right.', '2017-07-21 18:34:18.000000', NULL, 1),
(7524792, 1202801, 56492, '<td valign="top">Great juxtaposition between the cruise ship and the person on the lilo. Well seen and composed. The angle of the person''s feet direct you to look at the ship in all its detail; you explore from left to right and back again; the bow and/or stern direct the eye back down the frame of the picture; and when you reach the centre of the frame you eyes are drawn back through the water to the holday maker.</td>', 'Great juxtaposition between the cruise ship and the person on the lilo. Well seen and composed. The angle of the person''s feet direct you to look at the ship in all its detail; you explore from left to right and back again; the bow and/or stern direct the eye back down the frame of the picture; and when you reach the centre of the frame you eyes are drawn back through the water to the holday maker.', '2017-07-22 11:00:50.000000', NULL, 1),
(7524793, 1202803, 56492, '<td valign="top">I find this a very compelling image. There''s a lot going on, but the eye is always drawn back to the man in the boat; the seagulls frame him perfectly; the triangular lead-in of the boats directs the viewer very well. I feel that everything in the picture is coming at me and, like the boat driver, I am heading against the tide, so to speak.</td>', 'I find this a very compelling image. There''s a lot going on, but the eye is always drawn back to the man in the boat; the seagulls frame him perfectly; the triangular lead-in of the boats directs the viewer very well. I feel that everything in the picture is coming at me and, like the boat driver, I am heading against the tide, so to speak.', '2017-07-22 11:33:25.000000', NULL, 1),
(7524813, 1202617, 173844, '<td valign="top">Great presence here.  Looks like a bulldog with an under-slung jaw contemplating rushing the viewer.</td>', 'Great presence here.  Looks like a bulldog with an under-slung jaw contemplating rushing the viewer.', '2017-07-22 13:21:43.000000', NULL, 1),
(7524913, 1202626, 30364, '<td valign="top">I''ll have this one.  Thank you.</td>', 'I''ll have this one.  Thank you.', '2017-07-23 07:28:44.000000', NULL, 1),
(7524944, 1202770, 182284, '<td valign="top">Lovely shot.</td>', 'Lovely shot.', '2017-07-23 11:05:26.000000', NULL, 1),
(7524945, 1202784, 182284, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2017-07-23 11:05:49.000000', NULL, 1),
(7524946, 1202785, 182284, '<td valign="top">I wish the building was not in the background.8</td>', 'I wish the building was not in the background.8', '2017-07-23 11:07:03.000000', NULL, 1),
(7524947, 1202783, 182284, '<td valign="top">Scary ride. Makes my tummy flip looking at it.7</td>', 'Scary ride. Makes my tummy flip looking at it.7', '2017-07-23 11:07:49.000000', NULL, 1),
