(7524953, 1202517, 182284, '<td valign="top">I like it.6</td>', 'I like it.6', '2017-07-23 11:12:12.000000', NULL, 1),
(7524954, 1202745, 182284, '<td valign="top">I like the concept but you could have made this really pop by having more space at the top and less at the bottom. This would be a top ten for sure.7</td>', 'I like the concept but you could have made this really pop by having more space at the top and less at the bottom. This would be a top ten for sure.7', '2017-07-23 11:15:43.000000', NULL, 1),
(7524955, 1202574, 182284, '<td valign="top">The background is a bit busy. 7</td>', 'The background is a bit busy. 7', '2017-07-23 11:16:46.000000', NULL, 1),
(7524956, 1202789, 182284, '<td valign="top">I would give this a 10 if you had taken in landscape or done some cropping at the top and bottom.7</td>', 'I would give this a 10 if you had taken in landscape or done some cropping at the top and bottom.7', '2017-07-23 11:18:50.000000', NULL, 1),
(7524957, 1202617, 182284, '<td valign="top">Very nice shot.</td>', 'Very nice shot.', '2017-07-23 11:19:33.000000', NULL, 1),
