(7525008, 1202775, 182284, '<td valign="top">Very nice process. I wish the entire canoe was in the photo.6</td>', 'Very nice process. I wish the entire canoe was in the photo.6', '2017-07-23 21:26:32.000000', NULL, 1),
(7525209, 1202693, 30861, '<td valign="top">Weird... Last boat I owned was named "Arabesque" and, of course, I''m "Bear" albeit my running days are long over :-)</td>', 'Weird... Last boat I owned was named "Arabesque" and, of course, I''m "Bear" albeit my running days are long over :-)', '2017-07-24 13:05:27.000000', NULL, 1),
