(7525346, 1202783, 114285, '<td valign="top">That is crazy!!! Was this planned, awesome find! Ribbon for sure.</td>', 'That is crazy!!! Was this planned, awesome find! Ribbon for sure.', '2017-07-25 04:13:43.000000', NULL, 1),
